ENGINE=''
# Physical USB only. The browser reads this installer as data.
import base64,io,json,os,subprocess,sys,tempfile,uuid,zipfile,traceback
from pathlib import Path
if sys.version_info<(3,9):raise SystemExit('Python 3.9 or newer is required. No files changed.')
if os.geteuid()!=0:raise SystemExit('Use Hector original USB startup.')
os.umask(0o077)
with tempfile.TemporaryDirectory(prefix='poly-view-module-usb-') as temporary:
    temporary=Path(temporary)
    with zipfile.ZipFile(io.BytesIO(base64.b64decode(ENGINE))) as archive:
        for name in archive.namelist():
            if '/' in name or name.startswith('.'):raise ValueError('Invalid embedded verifier')
            (temporary/name).write_bytes(archive.read(name))
    sys.path.insert(0,str(temporary))
    import usb_release,platform_release,platform_service as service,platform_transaction as tr,system_support
    from publisher_release import PublisherPolicy
    import system_readiness
    from usb_entry_logging import Log,startup_log,verification_budget
    folder=Path(__file__).resolve().parent.parent
    sys.stdout=sys.stderr=Log([lambda: startup_log(service),folder/'POLY-VIEW-INSTALL.log'])
    system_readiness.wait(allow_absent=True,allow_legacy_upgrade=True,allow_initial_staging=True)
    with verification_budget():
        proof_raw=tr.regular(folder/'publisher.json',32768)
        proof=json.loads(proof_raw)
        files={name:tr.regular(tr.safe(folder,name),usb_release.LIMIT) for name in [*proof['files'],'publisher.json','publisher.sig']}
        rebuilt=io.BytesIO()
        with zipfile.ZipFile(rebuilt,'w',zipfile.ZIP_DEFLATED) as archive:
            for name,raw in files.items():archive.writestr(name,raw)
        inner,module,files=usb_release.read(rebuilt.getvalue(),PublisherPolicy())
        core,contents,_=platform_release.read(files['runtime.zip'],PublisherPolicy())
        repair=system_support.validate_runtime(core,contents,PublisherPolicy())
    sys.stdout.require_durable()
    release_sha=tr.digest(proof_raw)
    service.resume_pending()
    if not service.automatic_allowed(release_sha,module['id']):
        print('This release was already processed or recovery is pending. Use Settings > Module Manager for an explicit reinstall.');raise SystemExit(0)
    system_support.requirement(module,Path('/'),staging=True)
    inner_path=temporary/'module-release.zip';inner_path.write_bytes(inner)
    version=Path('/opt/hector-storage-manager/runtime-version.json')
    installed=False
    if version.exists():
        if version.is_symlink() or version.stat().st_uid!=0 or version.stat().st_mode&0o022:raise ValueError('Untrusted installed runtime')
        value=json.loads(tr.regular(version,4096))
        installed=(value.get('id')==platform_release.CORE_ID and value.get('api_version')==1
                   and 'repair-readiness-1' in value.get('capabilities',[]) and 'preset-preservation-1' in value.get('capabilities',[])
                   and (not module.get('support') or 'link-audio-support-1' in value.get('capabilities',[])))
    if not installed:platform_release.select(core,contents,Path('/overlay/lower'))
    bridge=system_support.bridge_for_release(files['runtime.zip'],PublisherPolicy()) if not installed else None
    prepared=system_support.usb_prepare_repair(repair,PublisherPolicy(),release_sha,allow_legacy_upgrade=not installed,bridge=bridge)
    if prepared['reboot_requested']:
        print('Flash Repair installed. Restarting automatically first. Leave USB inserted; module installation resumes next boot.')
        raise SystemExit(0)
    if installed:
        subprocess.run(['/usr/bin/python3','-I','-B','/opt/hector-storage-manager/app/platform_service.py','module',str(inner_path),release_sha],check=True)
    else:
        marker=Path('/run/hector-module-restarting')
        fd=os.open(marker,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600);os.close(fd)
        def stage_module(backup,job):
            subprocess.run(['/usr/bin/python3','-I','-B','/overlay/lower/opt/hector-storage-manager/app/module_offline.py',
                '--release',str(inner_path),'--backup',str(backup),'--firmware-root','/overlay/lower','--source-sha256',release_sha],check=True)
        request=dict(id=uuid.uuid4().hex,boot=Path('/proc/sys/kernel/random/boot_id').read_text().strip(),key=tr.digest(files['runtime.zip']),saved_patch=True,
                     source_release_sha256=release_sha,module_id=module['id'],module_name=module['name'])
        result=service.run_install(files['runtime.zip'],request,before_restart=stage_module)
        if not result.get('device_written') and not result.get('reboot_requested'):marker.unlink(missing_ok=True)
        print(json.dumps(result))
